<?php require '../config/database.php'; require '../includes/functions.php'; require_admin(); if($_SERVER['REQUEST_METHOD']==='POST'){ $q=$pdo->prepare("UPDATE repair_bookings SET status=? WHERE id=?"); $q->execute([$_POST['status'],(int)$_POST['id']]); } $rows=$pdo->query("SELECT * FROM repair_bookings ORDER BY created_at DESC")->fetchAll(); site_header('Repair Bookings'); ?>
<div class="admin-wrap"><h1>Repair Bookings</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="bookings.php">Bookings</a><a href="messages.php">Messages</a><a href="products.php">Products</a><a href="opportunities.php">Opportunities</a><a href="logout.php">Logout</a></nav><div class="table-wrap"><table><tr><th>ID / Customer</th><th>Device / Service</th><th>Date</th><th>Problem</th><th>Status</th></tr><?php foreach($rows as $r): ?><tr><td>#<?=$r['id']?> <?=e($r['customer_name'])?><br><?=e($r['phone'])?></td><td><?=e($r['device'])?> / <?=e($r['service'])?></td><td><?=e($r['booking_date'])?> <?=e($r['booking_time'])?></td><td><?=e($r['problem'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?= $r['status']==='pending'?'selected':'' ?>>pending</option><option <?= $r['status']==='confirmed'?'selected':'' ?>>confirmed</option><option <?= $r['status']==='completed'?'selected':'' ?>>completed</option><option <?= $r['status']==='cancelled'?'selected':'' ?>>cancelled</option></select><button class="btn">Save</button></form></td></tr><?php endforeach; ?></table></div></div><?php site_footer(); ?>